1	import { renderHook } from '@testing-library/react';
2	import { vi, describe, test, expect, beforeEach } from 'vitest';
3	
4	vi.mock('./useContentful', () => ({
5	  useContentfulEntries: vi.fn(),
6	}));
7	
8	import { useContentfulEntries } from './useContentful';
9	import { normaliseKey, useSizeGuide } from './useSizeGuide';
10	
11	const mockEntries = vi.mocked(useContentfulEntries) as ReturnType<typeof vi.fn>;
12	
13	describe('normaliseKey', () => {
14	  test('strips trailing numeric variant suffix', () => {
15	    expect(normaliseKey('clothing-op-4')).toBe('clothing_op');
16	  });
17	
18	  test('converts all hyphens to underscores', () => {
19	    expect(normaliseKey('womens-dresses')).toBe('womens_dresses');
20	  });
21	
22	  test('strips trailing suffix before converting hyphens', () => {
23	    expect(normaliseKey('size-guide-123')).toBe('size_guide');
24	  });
25	
26	  test('leaves keys with no suffix unchanged except hyphens', () => {
27	    expect(normaliseKey('hats')).toBe('hats');
28	  });
29	});
30	
31	describe('useSizeGuide — resolution priority', () => {
32	  beforeEach(() => {
33	    vi.clearAllMocks();
34	  });
35	
36	  const makeEntry = (key: string, locales?: string[]) => ({
37	    sys: { id: key, contentType: { sys: { id: 'sizeGuide' } } },
38	    fields: { key, internalTitle: key, label: key, hasCmInchToggle: false, locales },
39	  });
40	
41	  test('returns null when sizeGuideKey is undefined', () => {
42	    mockEntries.mockReturnValue({ data: [], isLoading: false });
43	    const { result } = renderHook(() => useSizeGuide(undefined, 'en-AU'));
44	    expect(result.current.sizeGuide).toBeNull();
45	  });
46	
47	  test('returns null when entries is undefined', () => {
48	    mockEntries.mockReturnValue({ data: undefined, isLoading: true });
49	    const { result } = renderHook(() => useSizeGuide('womens-dresses-1', 'en-AU'));
50	    expect(result.current.sizeGuide).toBeNull();
51	  });
52	
53	  test('priority 1: returns locale-specific key match over default', () => {
54	    // Contentful key uses underscore locale suffix (en_AU) per the sizeGuide key regex
55	    const localeEntry = makeEntry('size-guide__womens_dresses__en_AU');
56	    const defaultEntry = makeEntry('size-guide__womens_dresses');
57	    mockEntries.mockReturnValue({ data: [defaultEntry, localeEntry], isLoading: false });
58	    // SFCC passes hyphenated locale — hook canonicalises before matching
59	    const { result } = renderHook(() => useSizeGuide('womens-dresses-1', 'en-AU'));
60	    expect(result.current.sizeGuide).toBe(localeEntry);
61	  });
62	
63	  test('priority 2: returns locales[] field match when no exact locale key exists', () => {
64	    // Contentful locales[] values use underscores per the sizeGuide locales validation list
65	    const localesEntry = makeEntry('size-guide__womens_dresses__multi', ['en_AU', 'en_US']);
66	    const defaultEntry = makeEntry('size-guide__womens_dresses');
67	    mockEntries.mockReturnValue({ data: [defaultEntry, localesEntry], isLoading: false });
68	    const { result } = renderHook(() => useSizeGuide('womens-dresses-1', 'en-AU'));
69	    expect(result.current.sizeGuide).toBe(localesEntry);
70	  });
71	
72	  test('priority 3: falls back to default key when no locale-specific match', () => {
73	    const defaultEntry = makeEntry('size-guide__womens_dresses');
74	    mockEntries.mockReturnValue({ data: [defaultEntry], isLoading: false });
75	    const { result } = renderHook(() => useSizeGuide('womens-dresses-1', 'en-AU'));
76	    expect(result.current.sizeGuide).toBe(defaultEntry);
77	  });
78	
79	  test('returns null when no entry matches any priority', () => {
80	    mockEntries.mockReturnValue({ data: [makeEntry('size-guide__other')], isLoading: false });
81	    const { result } = renderHook(() => useSizeGuide('womens-dresses-1', 'en-AU'));
82	    expect(result.current.sizeGuide).toBeNull();
83	  });
84	
85	  test('normalises the SFCC key before matching', () => {
86	    const defaultEntry = makeEntry('size-guide__clothing_op');
87	    mockEntries.mockReturnValue({ data: [defaultEntry], isLoading: false });
88	    // SFCC key "clothing-op-4" normalises to "clothing_op"
89	    const { result } = renderHook(() => useSizeGuide('clothing-op-4', 'en-AU'));
90	    expect(result.current.sizeGuide).toBe(defaultEntry);
91	  });
92	
93	  test('exposes isLoading from useContentfulEntries', () => {
94	    mockEntries.mockReturnValue({ data: undefined, isLoading: true });
95	    const { result } = renderHook(() => useSizeGuide('womens-dresses-1', 'en-AU'));
96	    expect(result.current.isLoading).toBe(true);
97	  });
98	});
