1	import { describe, test, expect } from 'vitest';
2	import { convertCm, toDisplayRows } from './sizeGuideContent';
3	
4	describe('convertCm', () => {
5	  test('converts a whole cm value to inches rounded to 1 decimal', () => {
6	    expect(convertCm(76)).toBe(29.9);
7	  });
8	
9	  test('converts zero to zero', () => {
10	    expect(convertCm(0)).toBe(0);
11	  });
12	
13	  test('rounds to one decimal place', () => {
14	    // 60 * 0.393701 = 23.62206 → 23.6
15	    expect(convertCm(60)).toBe(23.6);
16	  });
17	});
18	
19	describe('toDisplayRows', () => {
20	  const baseRow = { label: 'Bust', convertible: true, values: ['76', '81', '86'] };
21	  const nonConvertibleRow = { label: 'Size', convertible: false, values: ['XS', 'S', 'M'] };
22	
23	  test('returns values unchanged when unit is cm', () => {
24	    const table = { columns: ['XS', 'S', 'M'], rows: [baseRow] };
25	    const result = toDisplayRows(table, 'cm');
26	    expect(result[0].cells).toEqual(['76', '81', '86']);
27	  });
28	
29	  test('converts convertible row values to inches when unit is inch', () => {
30	    const table = { columns: ['XS', 'S', 'M'], rows: [baseRow] };
31	    const result = toDisplayRows(table, 'inch');
32	    expect(result[0].cells).toEqual([29.9, 31.9, 33.9]);
33	  });
34	
35	  test('does not convert non-convertible rows', () => {
36	    const table = { columns: ['XS', 'S', 'M'], rows: [nonConvertibleRow] };
37	    const result = toDisplayRows(table, 'inch');
38	    expect(result[0].cells).toEqual(['XS', 'S', 'M']);
39	  });
40	
41	  test('converts range values (e.g. "56–59") correctly', () => {
42	    const rangeRow = { label: '', convertible: true, values: ['56–59'] };
43	    const table = { columns: [], rows: [rangeRow] };
44	    const result = toDisplayRows(table, 'inch');
45	    // 56 * 0.393701 = 22.0 → 22; 59 * 0.393701 = 23.2
46	    expect(result[0].cells[0]).toBe('22–23.2');
47	  });
48	
49	  test('converts range values separated by a hyphen (ASCII dash)', () => {
50	    const rangeRow = { label: '', convertible: true, values: ['56-59'] };
51	    const table = { columns: [], rows: [rangeRow] };
52	    const result = toDisplayRows(table, 'inch');
53	    expect(result[0].cells[0]).toBe('22–23.2');
54	  });
55	
56	  test('passes through non-numeric strings without converting', () => {
57	    const row = { label: 'Size', convertible: true, values: ['One Size'] };
58	    const table = { columns: [], rows: [row] };
59	    const result = toDisplayRows(table, 'inch');
60	    expect(result[0].cells[0]).toBe('One Size');
61	  });
62	
63	  test('preserves row metadata (label, spans, isHeader)', () => {
64	    const headerRow = { label: '', isHeader: true, convertible: false, values: ['OSFA'], spans: [3] };
65	    const table = { columns: [], rows: [headerRow] };
66	    const result = toDisplayRows(table, 'inch');
67	    expect(result[0].label).toBe('');
68	    expect(result[0].isHeader).toBe(true);
69	    expect(result[0].spans).toEqual([3]);
70	  });
71	});
