1	import React from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { BORDER_SECONDARY, BORDER_FOCUS } from './zimmTable.css';
4	
5	const ZIMM_TABLE_RECIPE = 'ZimmTable';
6	
7	export type ZimmTableRow = {
8	  label: string;
9	  cells: readonly (string | number)[];
10	  spans?: readonly number[];
11	  /** When true, renders this row as a bold group sub-header (labelless mode only). */
12	  isHeader?: boolean;
13	};
14	
15	export type ZimmTableProps = {
16	  columns: readonly string[];
17	  /** Sub-columns per main column. When > 1, main column headers span this many cells. */
18	  columnSpan?: number;
19	  /**
20	   * Sub-column labels rendered in a second thead row. Each label repeats once per main
21	   * column group (excluding the label column). The label column spans both header rows
22	   * via rowSpan=2. Used for the gloves table (S/M | M/L repeating under SHORT/LONG GLOVES).
23	   */
24	  subColumns?: readonly string[];
25	  rows: readonly ZimmTableRow[];
26	  /**
27	   * Omits the label column and thead entirely. Rows alternate between isHeader=true
28	   * (bold group header rendered as th) and isHeader=false (measurement values).
29	   * Used for the hat table's 3-level grouped layout.
30	   */
31	  labelless?: boolean;
32	  /**
33	   * Used with labelless: renders vertical cell dividers (borderLeft on non-first cells)
34	   * instead of row striping. Header rows get a dark bottom border; value rows get a light one.
35	   * Matches the Figma hat table variant.
36	   */
37	  bordered?: boolean;
38	};
39	
40	/**
41	 * Generic data table atom for the Size Guide drawer (SFCC-102).
42	 * Caller is responsible for passing display-ready values — unit conversion
43	 * happens upstream in SizeGuideContent, not here.
44	 *
45	 * columnSpan enables grouped headers (e.g. belt tables where XS/S spans 2 data columns).
46	 * row.spans controls per-cell colspan for merged rows. Omitting both fields preserves the
47	 * standard single-level layout used by clothing/shoe tables.
48	 */
49	export const ZimmTable = ({
50	  columns,
51	  columnSpan = 1,
52	  subColumns,
53	  rows,
54	  labelless = false,
55	  bordered = false,
56	}: ZimmTableProps) => {
57	  const variant = labelless && bordered ? 'bordered' : labelless ? 'labelless' : 'standard';
58	  const styles = useMultiStyleConfig(ZIMM_TABLE_RECIPE, { variant });
59	
60	  if (labelless && bordered) {
61	    // Pair consecutive rows into [headerRow, valueRow] groups, separated by a visual gap.
62	    const groups: ZimmTableRow[][] = [];
63	    for (let i = 0; i < rows.length; i += 2) groups.push(rows.slice(i, i + 2));
64	    // Derive total column count from the maximum span sum across all rows.
65	    const totalCols = Math.max(...rows.map((row) => (row.spans ?? row.cells.map(() => 1)).reduce((a, b) => a + b, 0)));
66	    return (
67	      <chakra.table __css={styles.table}>
68	        <chakra.colgroup>
69	          {Array.from({ length: totalCols }).map((_, i) => (
70	            <chakra.col key={i} width={`${(100 / totalCols).toFixed(4)}%`} />
71	          ))}
72	        </chakra.colgroup>
73	        <chakra.tbody>
74	          {groups.map((group, gi) => (
75	            <React.Fragment key={gi}>
76	              {gi > 0 && (
77	                <chakra.tr>
78	                  <chakra.td __css={styles.spacerTd} colSpan={totalCols} />
79	                </chakra.tr>
80	              )}
81	              {group.map((row, ri) =>
82	                row.isHeader ? (
83	                  <chakra.tr key={ri}>
84	                    {row.cells.map((cell, j) => (
85	                      <chakra.th
86	                        key={j}
87	                        __css={styles.th}
88	                        colSpan={row.spans?.[j] ?? 1}
89	                        textAlign="center"
90	                        borderBottom={BORDER_FOCUS}
91	                        borderLeft={j > 0 ? BORDER_SECONDARY : undefined}
92	                      >
93	                        {cell}
94	                      </chakra.th>
95	                    ))}
96	                  </chakra.tr>
97	                ) : (
98	                  <chakra.tr key={ri}>
99	                    {row.cells.map((cell, j) => (
100	                      <chakra.td
101	                        key={j}
102	                        __css={styles.td}
103	                        colSpan={row.spans?.[j] ?? 1}
104	                        textAlign="center"
105	                        borderBottom={BORDER_SECONDARY}
106	                        borderLeft={j > 0 ? BORDER_SECONDARY : undefined}
107	                      >
108	                        {cell}
109	                      </chakra.td>
110	                    ))}
111	                  </chakra.tr>
112	                ),
113	              )}
114	            </React.Fragment>
115	          ))}
116	        </chakra.tbody>
117	      </chakra.table>
118	    );
119	  }
120	
121	  if (labelless) {
122	    return (
123	      <chakra.table __css={styles.table}>
124	        <chakra.tbody>
125	          {rows.map((row, i) =>
126	            row.isHeader ? (
127	              <chakra.tr key={i} bg={i % 2 !== 0 ? 'var(--zimm-color-bg-02)' : undefined}>
128	                {row.cells.map((cell, j) => (
129	                  <chakra.th
130	                    key={j}
131	                    __css={styles.th}
132	                    colSpan={row.spans?.[j] ?? 1}
133	                    textAlign="center"
134	                    borderBottom={BORDER_SECONDARY}
135	                  >
136	                    {cell}
137	                  </chakra.th>
138	                ))}
139	              </chakra.tr>
140	            ) : (
141	              <chakra.tr key={i} bg={i % 2 !== 0 ? 'var(--zimm-color-bg-02)' : undefined}>
142	                {row.cells.map((cell, j) => (
143	                  <chakra.td
144	                    key={j}
145	                    __css={styles.td}
146	                    colSpan={row.spans?.[j] ?? 1}
147	                    textAlign="center"
148	                    borderBottom={BORDER_SECONDARY}
149	                  >
150	                    {cell}
151	                  </chakra.td>
152	                ))}
153	              </chakra.tr>
154	            ),
155	          )}
156	        </chakra.tbody>
157	      </chakra.table>
158	    );
159	  }
160	
161	  return (
162	    <chakra.table __css={styles.table}>
163	      <chakra.thead>
164	        <chakra.tr>
165	          {columns.map((col, j) => (
166	            <chakra.th
167	              key={j}
168	              __css={styles.th}
169	              colSpan={j === 0 ? 1 : columnSpan}
170	              rowSpan={subColumns && subColumns.length > 0 && j === 0 ? 2 : 1}
171	              textAlign={j === 0 ? 'left' : 'center'}
172	              verticalAlign={subColumns && subColumns.length > 0 && j === 0 ? 'middle' : undefined}
173	              borderBottom={subColumns && subColumns.length > 0 && j > 0 ? 'none' : BORDER_FOCUS}
174	              borderRight={columnSpan > 1 && j > 0 && j < columns.length - 1 ? BORDER_SECONDARY : undefined}
175	            >
176	              {col}
177	            </chakra.th>
178	          ))}
179	        </chakra.tr>
180	        {subColumns && subColumns.length > 0 && (
181	          <chakra.tr>
182	            {columns.slice(1).flatMap((_, colIdx) =>
183	              subColumns.map((sub, subIdx) => (
184	                <chakra.th
185	                  key={`${colIdx}-${subIdx}`}
186	                  __css={styles.th}
187	                  textAlign="center"
188	                  borderBottom={BORDER_FOCUS}
189	                  borderRight={
190	                    colIdx < columns.slice(1).length - 1 && subIdx === subColumns.length - 1
191	                      ? BORDER_SECONDARY
192	                      : undefined
193	                  }
194	                >
195	                  {sub}
196	                </chakra.th>
197	              )),
198	            )}
199	          </chakra.tr>
200	        )}
201	      </chakra.thead>
202	      <chakra.tbody>
203	        {rows.map((row, i) => (
204	          <chakra.tr key={i} bg={i % 2 !== 0 ? 'var(--zimm-color-bg-02)' : undefined}>
205	            <chakra.td __css={styles.labelTd} borderBottom={BORDER_SECONDARY}>
206	              {row.label}
207	            </chakra.td>
208	            {row.cells.map((cell, j) => {
209	              const hasGroupRightBorder =
210	                columnSpan > 1 && j < row.cells.length - 1 && (row.spans ? true : (j + 1) % columnSpan === 0);
211	              return (
212	                <chakra.td
213	                  key={j}
214	                  __css={styles.td}
215	                  colSpan={row.spans?.[j] ?? 1}
216	                  textAlign="center"
217	                  borderBottom={BORDER_SECONDARY}
218	                  borderRight={hasGroupRightBorder ? BORDER_SECONDARY : undefined}
219	                >
220	                  {cell}
221	                </chakra.td>
222	              );
223	            })}
224	          </chakra.tr>
225	        ))}
226	      </chakra.tbody>
227	    </chakra.table>
228	  );
229	};
