1	import { useState, useEffect } from 'react';
2	import { getContentfulConfig } from '../config/contentful';
3	import type { ContentfulAsset } from '../types/contentful';
4	
5	type ContentfulLink = {
6	  sys: {
7	    type: 'Link';
8	    linkType: 'Asset' | 'Entry';
9	    id: string;
10	  };
11	};
12	
13	type ContentfulRawEntry = {
14	  fields: Record<string, ContentfulLink | ContentfulAsset | unknown>;
15	  [key: string]: unknown;
16	};
17	
18	type ContentfulEntriesResponse = {
19	  items: ContentfulRawEntry[];
20	  includes?: {
21	    Asset?: ContentfulAsset[];
22	  };
23	};
24	
25	// Exported (alongside buildContentfulUrl/resolveLinkedAssets below) purely so they can be
26	// unit-tested directly as pure functions, the same way footer/index.tsx exports scopeToRegion —
27	// not part of this module's intended public surface for other callers.
28	//
29	// Throws rather than returning a nullable config so every caller's existing try/catch
30	// (which already converts a thrown Error into `error` state) handles the missing-config
31	// case for free, instead of each hook duplicating its own early-return branch.
32	export const getValidatedContentfulConfig = () => {
33	  const config = getContentfulConfig();
34	  if (!config.spaceId || !config.accessToken) {
35	    throw new Error('Contentful configuration missing');
36	  }
37	  return config;
38	};
39	
40	// include=2 is fixed at every call site — the minimum depth that resolves linked assets,
41	// which resolveLinkedAssets below assumes is already populated in the response.
42	export const buildContentfulUrl = (
43	  query: string,
44	  config: ReturnType<typeof getContentfulConfig>,
45	  preview: boolean,
46	  locale?: string,
47	): string => {
48	  const { spaceId, accessToken, previewAccessToken, environment } = config;
49	  const baseUrl = preview ? 'https://preview.contentful.com' : 'https://cdn.contentful.com';
50	  const token = preview ? previewAccessToken : accessToken;
51	  const localeParam = locale ? `&locale=${encodeURIComponent(locale)}` : '';
52	  return `${baseUrl}/spaces/${spaceId}/environments/${environment}/entries?${query}&access_token=${token}&include=2${localeParam}`;
53	};
54	
55	export const resolveLinkedAssets = <T extends ContentfulRawEntry>(
56	  item: T,
57	  includes?: ContentfulEntriesResponse['includes'],
58	): T => {
59	  // Clone fields too, not just the top-level item — a shallow `{ ...item }` still shares the
60	  // same `fields` object reference with the original, so writing into resolvedItem.fields
61	  // below would otherwise mutate the raw Contentful response entry in place.
62	  const resolvedItem = { ...item, fields: { ...item.fields } };
63	  if (item.fields) {
64	    Object.keys(item.fields).forEach((fieldKey) => {
65	      const fieldValue = item.fields[fieldKey] as ContentfulLink;
66	      if (fieldValue?.sys?.type === 'Link' && fieldValue?.sys?.linkType === 'Asset') {
67	        const linked = includes?.Asset?.find((asset) => asset.sys.id === fieldValue.sys.id);
68	        if (linked) resolvedItem.fields[fieldKey] = linked;
69	      }
70	    });
71	  }
72	  return resolvedItem;
73	};
74	
75	export const useContentfulEntry = <T>(entryId: string, preview = false, locale?: string) => {
76	  const [data, setData] = useState<T | null>(null);
77	  const [isLoading, setIsLoading] = useState(true);
78	  const [error, setError] = useState<Error | null>(null);
79	
80	  useEffect(() => {
81	    const controller = new AbortController();
82	
83	    // Reset rather than leaving the previous request's data/error in place — without this,
84	    // a locale change on an already-mounted consumer (e.g. UiCopyProvider) would keep
85	    // rendering the old locale's content until the new fetch resolves.
86	    setIsLoading(true);
87	    setError(null);
88	    setData(null);
89	
90	    const fetchEntry = async () => {
91	      try {
92	        const config = getValidatedContentfulConfig();
93	        // Search endpoint with sys.id, so include=2 still resolves linked assets.
94	        const url = buildContentfulUrl(`sys.id=${entryId}`, config, preview, locale);
95	        const response = await fetch(url, { signal: controller.signal });
96	
97	        if (!response.ok) {
98	          throw new Error(`Contentful API error: ${response.status}`);
99	        }
100	
101	        const result: ContentfulEntriesResponse = await response.json();
102	        const item = result.items[0];
103	        if (!item) {
104	          throw new Error(`Entry ${entryId} not found`);
105	        }
106	        setData(resolveLinkedAssets(item, result.includes) as T);
107	      } catch (err) {
108	        if (err instanceof DOMException && err.name === 'AbortError') return;
109	        setError(err instanceof Error ? err : new Error('Unknown error'));
110	      } finally {
111	        // Guards against the superseded request's own `finally` running after this effect
112	        // has already started a new one (e.g. deps changed before the prior fetch settled) —
113	        // controller.signal.aborted flips synchronously the instant cleanup calls abort(),
114	        // so by the time an aborted request's finally runs, it can tell it's no longer current.
115	        if (!controller.signal.aborted) setIsLoading(false);
116	      }
117	    };
118	
119	    void fetchEntry();
120	    return () => controller.abort();
121	  }, [entryId, preview, locale]);
122	
123	  return { data, isLoading, error };
124	};
125	
126	export const useContentfulEntries = <T>(contentType: string, preview = false, locale?: string, enabled = true) => {
127	  const [data, setData] = useState<T[] | null>(null);
128	  const [isLoading, setIsLoading] = useState(true);
129	  const [error, setError] = useState<Error | null>(null);
130	
131	  useEffect(() => {
132	    if (!enabled) {
133	      setData(null);
134	      setError(null);
135	      setIsLoading(false);
136	      return;
137	    }
138	
139	    const controller = new AbortController();
140	
141	    // Reset rather than leaving the previous request's data/error in place — without this,
142	    // a locale change on an already-mounted consumer (e.g. UiCopyProvider) would keep
143	    // rendering the old locale's content until the new fetch resolves.
144	    setIsLoading(true);
145	    setError(null);
146	    setData(null);
147	
148	    const fetchEntries = async () => {
149	      try {
150	        const config = getValidatedContentfulConfig();
151	        const url = buildContentfulUrl(`content_type=${contentType}`, config, preview, locale);
152	        const response = await fetch(url, { signal: controller.signal });
153	
154	        if (!response.ok) {
155	          const errorText = await response.text();
156	          console.error('Contentful API error response:', errorText);
157	          throw new Error(`Contentful API error: ${response.status}`);
158	        }
159	
160	        const result: ContentfulEntriesResponse = await response.json();
161	        const resolvedItems = result.items.map((item) => resolveLinkedAssets(item, result.includes));
162	        setData(resolvedItems as T[]);
163	      } catch (err) {
164	        if (err instanceof DOMException && err.name === 'AbortError') return;
165	        console.error('Contentful fetch error:', err);
166	        setError(err instanceof Error ? err : new Error('Unknown error'));
167	      } finally {
168	        // See useContentfulEntry's identical guard above for why this check is needed.
169	        if (!controller.signal.aborted) setIsLoading(false);
170	      }
171	    };
172	
173	    void fetchEntries();
174	    return () => controller.abort();
175	  }, [contentType, preview, locale, enabled]);
176	
177	  return { data, isLoading, error };
178	};
