overrides/app/types/contentful.ts
export type ContentfulAsset = {
  sys: {
    id: string;
  };
  fields: {
    title: string;
    description?: string;
    file: {
      url: string;
      fileName: string;
      contentType: string;
      details: {
        size: number;
        image?: {
          width: number;
          height: number;
        };
      };
    };
  };
};

export type ContentfulRichText = {
  nodeType: string;
  data: Record<string, unknown>;
  content: ContentfulRichTextNode[];
};

export type ContentfulRichTextNode = {
  nodeType: string;
  value?: string;
  data?: Record<string, unknown>;
  content?: ContentfulRichTextNode[];
  marks?: Array<{
    type: string;
  }>;
};

// ---------------------------------------------------------------------------
// Image content type
// Reusable "asset + accessible metadata" primitive — see
// scripts/contentful/content-types/image.js. Reference this (not ContentfulAsset
// directly) from any field that should let an editor set real alt text/caption per usage
// rather than falling back to the underlying asset's own title/description.
// ---------------------------------------------------------------------------

export type ImageEntry = {
  sys: {
    id: string;
    contentType: { sys: { id: 'image' } };
  };
  fields: {
    /** Editor-facing label only — not localized, not rendered. See image.js's own comment. */
    internalTitle: string;
    asset?: ContentfulAsset;
    /** Purely decorative — screen readers should skip it (empty alt). Editorial flag, not
     *  inferred from the presence/absence of altText. */
    decorative?: boolean;
    altText?: string;
    caption?: string;
    link?: ContentfulRichText;
  };
};

export type HomepageEntry = {
  sys: {
    id: string;
    contentType: {
      sys: {
        id: 'homepage';
      };
    };
  };
  fields: {
    heroBanner?: ContentfulAsset;
    duplexSection?: ContentfulRichText;
    videoEmbed?: ContentfulAsset;
    productHero?: string;
  };
};

// ---------------------------------------------------------------------------
// Region content type
// Canonical, referenceable region/storefront entity — any content type needing
// region-scoping (link, footerConfig, etc.) references this via a `regions` field
// instead of duplicating a hardcoded site-ID list. Seeded with one entry per SFCC site
// by scripts/contentful/setup/seedRegions.mjs.
// ---------------------------------------------------------------------------

export type RegionEntry = {
  sys: {
    id: string;
    contentType: { sys: { id: 'region' } };
  };
  fields: {
    /** SFCC site ID (e.g. 'ZimmermannAU') — the canonical join key. */
    siteId: string;
    /** Editor-facing display name (e.g. 'Australia'). Admin label, not shopper-facing. */
    label: string;
    /** Informational only — mirrors the site's primary locale. */
    locale?: string;
  };
};

// ---------------------------------------------------------------------------
// Footer content types
// Live content types — see scripts/contentful/content-types/link.js, navGroup.js,
// footerConfig.js, authored via scripts/contentful/buildTemplate.js and installed per
// environment via scripts/contentful/setup/installTemplate.mjs.
// ---------------------------------------------------------------------------

export type LinkEntry = {
  sys: {
    id: string;
    contentType: { sys: { id: 'link' } };
  };
  fields: {
    label: string;
    href: string;
    /**
     * Regions this link applies to. Omitted/empty = applies to all regions (the
     * default/global case) — see overrides/app/utils/resolveByRegion.ts.
     */
    regions?: ReadonlyArray<RegionEntry>;
  };
};

/**
 * A reusable "heading + list of links" column — generalised from the footer-only
 * `footerNavGroup` type (see scripts/contentful/content-types/navGroup.js) so the header
 * mega-menu can reference the same shape. `showContactChannels` is a footer-only flag;
 * a header mega-menu group simply never sets it.
 */
export type NavGroupEntry = {
  sys: {
    id: string;
    contentType: { sys: { id: 'navGroup' } };
  };
  fields: {
    /** Editor-facing label only — not localized, not rendered. */
    internalTitle: string;
    heading: string;
    readonly links: ReadonlyArray<LinkEntry>;
    /**
     * Renders the contact-channel icon row beneath this group's links.
     *
     * A flag rather than matching the heading text: `heading` is a localised Contentful
     * value, so `heading === 'Contact'` silently stops matching the moment an editor writes
     * "Kontakt" or "Contacto" — and this footer ships to eight storefronts.
     */
    showContactChannels?: boolean;
  };
};

export type FooterConfigEntry = {
  sys: {
    id: string;
    contentType: { sys: { id: 'footerConfig' } };
  };
  fields: {
    internalTitle: string;
    subscribeHeading?: string;
    subscribeBody?: string;
    // Read-only both ways. The footer only ever .maps these, but footer/index.stories.content.ts's
    // FOOTER_FIXTURE is a plain module singleton multiple stories in index.stories.tsx read
    // directly, so an in-place push/sort/index-assign anywhere would corrupt every other
    // story reading the same object. ReadonlyArray blocks push/pop/splice/sort/reverse/
    // index-assign/length; the `readonly` property modifier additionally blocks swapping the
    // whole array out. Matches BottomBarProps.legalLinks in footer/index.tsx, which already
    // types its array as ReadonlyArray<>.
    readonly navGroups: ReadonlyArray<NavGroupEntry>;
    readonly legalLinks?: ReadonlyArray<LinkEntry>;
    copyrightOwner?: string;
    // Each channel's accessible-name label is co-located with its own href rather than a
    // generic uiCopy string — see footerConfig.js's field comment for why. Optional: an
    // entry authored before these fields existed falls back to ZimmContactIconRow's own
    // default label.
    phoneHref?: string;
    phoneLabel?: string;
    whatsAppHref?: string;
    whatsAppLabel?: string;
    emailHref?: string;
    emailLabel?: string;
    /**
     * Regions this footer applies to. Omitted/empty = the default/global footer for its
     * locale. A narrower-scoped entry takes precedence when resolving which footerConfig
     * to render for a given site — see overrides/app/utils/resolveByRegion.ts.
     */
    readonly regions?: ReadonlyArray<RegionEntry>;
  };
};

// ---------------------------------------------------------------------------
// UI copy content type
// One entry per UI string (error text, input placeholders, CTA labels, etc.) — fetched
// in bulk and reduced into a key→value map. See scripts/contentful/content-types/uiCopy.js.
// ---------------------------------------------------------------------------

export type UiCopyEntry = {
  sys: {
    id: string;
    contentType: { sys: { id: 'uiCopy' } };
  };
  fields: {
    /** Editor-facing friendly name — never rendered in the app. See uiCopy.js's title field. */
    title: string;
    key: string;
    value: string;
    description?: string;
  };
};

// ---------------------------------------------------------------------------
// Header navigation content types
// Live content types — see scripts/contentful/content-types/headerNavItem.js,
// headerNavigation.js, authored via scripts/contentful/buildTemplate.js and installed per
// environment via scripts/contentful/setup/installTemplate.mjs.
// ---------------------------------------------------------------------------

export type HeaderNavItemEntry = {
  sys: {
    id: string;
    contentType: { sys: { id: 'headerNavItem' } };
  };
  fields: {
    label: string;
    /** Set only for a direct-link item (no dropdown) — see headerNavItem.js's description. */
    href?: string;
    /** 0/omitted columns = direct link via `href`; 1+ = mega-menu. */
    readonly columns?: ReadonlyArray<NavGroupEntry>;
    /** Desktop/tablet only — splits `columns` into two side-by-side columns instead of the
     *  default single stacked column. See megaMenuContent/toMegaMenuItem.ts. */
    twoColumnLayout?: boolean;
    /** Links the reusable `image` primitive, not a raw Asset — see ImageEntry's own comment. */
    promoImage?: ImageEntry;
    /**
     * Regions this item applies to. Omitted/empty = applies to all regions (the
     * default/global case) — see overrides/app/utils/resolveByRegion.ts.
     */
    readonly regions?: ReadonlyArray<RegionEntry>;
  };
};

export type HeaderNavigationEntry = {
  sys: {
    id: string;
    contentType: { sys: { id: 'headerNavigation' } };
  };
  fields: {
    internalTitle: string;
    readonly items: ReadonlyArray<HeaderNavItemEntry>;
    /**
     * Regions this header nav applies to. Omitted/empty = the default/global header nav
     * for its locale. A narrower-scoped entry takes precedence when resolving which
     * headerNavigation to render for a given site — see overrides/app/utils/resolveByRegion.ts.
     */
    readonly regions?: ReadonlyArray<RegionEntry>;
  };
};

export type AnyContentfulEntry = {
  sys: {
    id: string;
    contentType?: {
      sys: {
        id: string;
      };
    };
  };
  fields: Record<string, unknown>;
};

export type ContentfulResponse<T> = {
  sys: {
    type: string;
  };
  fields: T;
};

// ---------------------------------------------------------------------------
// Size Guide content type
// One entry per size guide, keyed by a structured `key` field
// (pattern: size-guide__{slug} or size-guide__{slug}__{locale}).
// Fetched in bulk and resolved client-side via useSizeGuide — see
// overrides/app/hooks/useSizeGuide.ts.
// ---------------------------------------------------------------------------

export type SizeGuideTableRow = {
  label: string;
  convertible: boolean;
  values: (string | number)[];
  spans?: number[];
  /** When true, this row renders as a bold sub-header (for labelless grouped tables). */
  isHeader?: boolean;
};

export type SizeGuideTable = {
  columns: string[];
  columnSpan?: number;
  /**
   * Sub-column labels rendered in a second thead row beneath the main column headers.
   * Each label repeats once per main column group. The first column (SIZE/label) spans
   * both header rows via rowSpan=2. Used for the gloves table (S/M | M/L repeating
   * under SHORT GLOVES and LONG GLOVES).
   */
  subColumns?: string[];
  rows: SizeGuideTableRow[];
  /**
   * When true, omits the label column and thead entirely. Rows alternate between
   * isHeader=true (bold group header) and isHeader=false (measurement values).
   * Used for the hat table's 3-level grouped layout.
   */
  labelless?: boolean;
  /**
   * Optional custom section heading rendered above this table. When present,
   * overrides the default FormattedMessage label (e.g. "SIZE CONVERSIONS").
   * Allows reusing bodyMeasurementsTable/garmentMeasurementsTable for guides
   * that need multiple size conversion sections with different titles (e.g. jewellery).
   */
  heading?: string;
  /** When true, suppresses the section heading entirely (e.g. the hat table). */
  hideHeading?: boolean;
};

export type SizeGuideEntry = {
  sys: { id: string; contentType: { sys: { id: 'sizeGuide' } } };
  fields: {
    internalTitle: string;
    key: string;
    label: string;
    /** Typed but not rendered — @contentful/rich-text-react-renderer not installed (Hard Rule #7). */
    measurementInstructions?: ContentfulRichText;
    sizeConversionsDescription?: string;
    sizeConversionsTable?: SizeGuideTable;
    bodyMeasurementsDescription?: string;
    bodyMeasurementsTable?: SizeGuideTable;
    garmentMeasurementsDescription?: string;
    garmentMeasurementsTable?: SizeGuideTable;
    hasCmInchToggle: boolean;
    /**
     * Initial unit for the CM/INCH toggle. Defaults to 'cm' when absent.
     * Set to 'inch' for guides where inch is the primary display unit (e.g. hats, gloves).
     */
    defaultUnit?: 'cm' | 'inch';
    localeNote?: string;
    locales?: string[];
    /** Rendered only when all three table fields are absent. */
    image?: ContentfulAsset;
  };
};

