20	const mockGetConfig = vi.mocked(getContentfulConfig);
21	
22	const BASE_CONFIG = {
23	  spaceId: 'space123',
24	  environment: 'master',
25	  accessToken: 'cda-token',
26	  previewAccessToken: 'cpa-token',
27	};
28	
29	const entry = (id: string) => ({ sys: { id }, fields: { key: id, value: id } });
30	
31	// Each fetch() call gets its own controllable promise so a test can decide exactly when (or
32	// whether) it resolves, and can inspect the URL/AbortSignal it was called with.
33	type PendingFetch = { url: string; resolve: (items: ReturnType<typeof entry>[]) => void; signal?: AbortSignal };
34	let pending: PendingFetch[] = [];
35	
36	const mockFetch = vi.fn((url: string, init?: RequestInit) => {
37	  return new Promise((resolve, reject) => {
38	    init?.signal?.addEventListener('abort', () => reject(new DOMException('Aborted', 'AbortError')));
39	    pending.push({
40	      url,
41	      signal: init?.signal ?? undefined,
42	      resolve: (items) => resolve({ ok: true, json: () => Promise.resolve({ items }) } as Response),
43	    });
44	  });
45	});
46	
47	describe('useContentfulEntries — locale-change state handling', () => {
48	  beforeEach(() => {
49	    vi.clearAllMocks();
50	    pending = [];
51	    mockGetConfig.mockReturnValue(BASE_CONFIG);
52	    vi.stubGlobal('fetch', mockFetch);
53	  });
54	
55	  afterEach(() => {
56	    vi.unstubAllGlobals();
57	  });
58	
59	  test('resets data and isLoading as soon as a dependency (locale) changes, not just on mount', async () => {
60	    const { result, rerender } = renderHook(
61	      ({ locale }) => useContentfulEntries<{ id: string }>('uiCopy', false, locale),
62	      {
63	        initialProps: { locale: 'en-AU' },
64	      },
65	    );
66	
67	    expect(pending).toHaveLength(1);
68	    expect(pending[0].url).toContain('locale=en-AU');
69	    act(() => pending[0].resolve([entry('a')]));
70	    await waitFor(() => expect(result.current.isLoading).toBe(false));
71	    expect(result.current.data).toEqual([entry('a')]);
72	
73	    rerender({ locale: 'en-GB' });
74	
75	    // Reset happens synchronously at the start of the new effect, before the new fetch even
76	    // settles — a consumer must not keep rendering the previous locale's data in the meantime.
77	    expect(result.current.isLoading).toBe(true);
78	    expect(result.current.data).toBeNull();
79	    expect(pending[1].url).toContain('locale=en-GB');
80	
81	    act(() => pending[1].resolve([entry('b')]));
82	    await waitFor(() => expect(result.current.isLoading).toBe(false));
83	    expect(result.current.data).toEqual([entry('b')]);
84	  });
85	
86	  test('an aborted previous request cannot clear isLoading for the request that superseded it', async () => {
87	    const { result, rerender } = renderHook(
88	      ({ locale }) => useContentfulEntries<{ id: string }>('uiCopy', false, locale),
89	      {
90	        initialProps: { locale: 'en-AU' },
91	      },
92	    );
93	
94	    expect(pending).toHaveLength(1);
95	    const firstSignal = pending[0].signal;
96	
97	    // Change locale before the first request ever settles — cleanup aborts it, and the new
98	    // effect run starts a second request.
99	    rerender({ locale: 'en-GB' });
100	
101	    expect(pending).toHaveLength(2);
102	    expect(firstSignal?.aborted).toBe(true);
103	    expect(result.current.isLoading).toBe(true);
104	
105	    // Let the aborted first request's rejection actually propagate through its catch/finally —
106	    // without the abort guard, its finally would call setIsLoading(false) here even though the
107	    // second (superseding) request is still genuinely in flight.
108	    await act(async () => {
109	      await Promise.resolve();
110	      await Promise.resolve();
111	    });
112	    expect(result.current.isLoading).toBe(true);
113	    expect(result.current.data).toBeNull();
114	
115	    act(() => pending[1].resolve([entry('b')]));
116	    await waitFor(() => expect(result.current.isLoading).toBe(false));
117	    expect(result.current.data).toEqual([entry('b')]);
118	  });
119	});
